const vocab = (rows) => rows.map((row) => { const [han,pinyin,zhuyin,vi] = row.split('|'); return {han,pinyin,zhuyin,vi}; });
const line = (speaker,han,pinyin,vi) => ({speaker,han,pinyin,vi});
const text = (han,pinyin,vi) => ({han,pinyin,vi});
const question = (question,choices,answer,explanation) => ({question,choices,answer,explanation});
const lesson = (data) => ({minutes:15,sourceIds:['ntnu','moe-dict','tocfl'],...data});

