    {number:2,name:'Thanh 2 · đi lên',pinyin:'má',zhuyin:'ㄇㄚˊ',example:'麻 · cây gai; tê',tip:'Bắt đầu ở mức vừa, nâng giọng lên.'},
    {number:3,name:'Thanh 3 · thấp',pinyin:'mǎ',zhuyin:'ㄇㄚˇ',example:'馬 · ngựa',tip:'Khi đọc riêng có thể hạ rồi nhấc nhẹ. Trong chuỗi lời nói thường giữ thấp; không cố uốn đủ ở mọi âm tiết.'},
    {number:4,name:'Thanh 4 · đi xuống',pinyin:'mà',zhuyin:'ㄇㄚˋ',example:'罵 · mắng',tip:'Từ cao hạ dứt khoát xuống; tránh kéo dài.'},
    {number:0,name:'Âm nhẹ · ngắn, nhẹ',pinyin:'ma',zhuyin:'˙ㄇㄚ',example:'嗎 · trợ từ hỏi',tip:'Đọc ngắn, không nhấn; độ cao phụ thuộc âm tiết trước.'}
