const card = (bookNumber,key,title,pattern,explanation,han,pinyin,vi,pitfall,extra=[]) => ({
  id:`b${bookNumber}-${key}`,bookNumber,lessonIds:[lessons[bookNumber-1].id],
  title,level:bookNumber<=6?'A1':'A2',pattern,explanation,
  examples:[text(han,pinyin,vi)],pitfall,sourceIds:['textbook','ntnu',...extra]
});

// Every item in the supplied book's lesson-focus table (PDF 19/21/23) is represented.
export const grammar = [
  card(1,'a-not-a','Hỏi A不A','Động từ + 不 + động từ？','Lặp động từ với 不 ở giữa để hỏi có/không. Với 是: 是不是.','你是不是學生？','Nǐ shì bù shì xuéshēng?','Bạn có phải là sinh viên không?','Câu hỏi A不A cơ bản không thêm 嗎 cuối câu.'),
  card(1,'ma','Câu hỏi với 嗎','Câu trần thuật + 嗎？','Thêm 嗎 để hỏi có/không; giữ trật tự câu trần thuật.','你是越南人嗎？','Nǐ shì Yuènán rén ma?','Bạn là người Việt Nam phải không?','Không thêm 嗎 vào câu hỏi thông tin đơn giản đã có 什麼/哪裡.'),
  card(1,'answers','Trả lời khẳng định và phủ định 不','Động từ / 不 + động từ','Thường trả lời bằng động từ/cụm vị ngữ của câu hỏi. 不 phủ định thói quen, trạng thái hoặc ý định.','你喝茶嗎？我不喝茶。','Nǐ hē chá ma? Wǒ bù hē chá.','Bạn có uống trà không? Tôi không uống trà.','Không dùng 是 để trả lời khẳng định mọi câu hỏi; hỏi 喝茶 có thể đáp 喝/不喝.'),
  card(1,'hen','Tính từ làm vị ngữ và 很','Chủ ngữ + 很 + tính từ','Trong câu miêu tả trung tính, 很 giúp câu tự nhiên và không luôn cần dịch “rất”.','今天很熱。','Jīntiān hěn rè.','Hôm nay trời nóng.','Không tự thêm 是 trước 很熱 trong câu đơn giản.'),
  card(1,'ne','Hỏi lại với 呢','Chủ đề + 呢？','Dùng khi ngữ cảnh đã có nội dung để hỏi tiếp người hoặc đối tượng khác.','我叫明。你呢？','Wǒ jiào Míng. Nǐ ne?','Tôi tên Minh. Còn bạn?','呢 không thay 嗎 trong mọi câu hỏi.'),
  card(2,'de-owner','的 chỉ sở hữu','Người sở hữu + 的 + danh từ','的 thể hiện quan hệ của người/vật với danh từ phía sau.','這是我的書。','Zhè shì wǒ de shū.','Đây là sách của tôi.','Có thể lược 的 trong 我媽媽; không suy rộng cách lược cho mọi cụm.'),
  card(2,'de-modifier','的 nối phần bổ nghĩa','Phần mô tả + 的 + danh từ','的 có thể nối tính từ hoặc cụm mô tả với danh từ.','她是很好的老師。','Tā shì hěn hǎo de lǎoshī.','Cô ấy là một giáo viên tốt.','Nhiều tính từ một âm tiết gắn trực tiếp với danh từ: 大學校; không phải mọi chỗ đều cần 的.'),
  card(2,'you','Sở hữu với 有','Chủ ngữ + 有 / 沒有 + danh từ','有 nói có/sở hữu; 沒有 là phủ định cơ bản.','我有一個妹妹。','Wǒ yǒu yī ge mèimei.','Tôi có một em gái.','Không nói 不有 để phủ định sở hữu.'),
  card(2,'dou','Toàn bộ với 都','Nhóm được nói đến + 都 + vị ngữ','都 đứng trước vị ngữ và bao quát nhóm ở phía trước.','我們都是學生。','Wǒmen dōu shì xuéshēng.','Chúng tôi đều là sinh viên.','都不 = tất cả đều không; 不都 = không phải tất cả đều. Hai trật tự khác nghĩa.'),
  card(2,'ge-zhang','Lượng từ 個 và 張','Số + 個 / 張 + danh từ','個 thông dụng với người/nhiều vật; 張 thường cho vật có bề mặt phẳng như bàn, ảnh.','我家有一張桌子。','Wǒ jiā yǒu yī zhāng zhuōzi.','Nhà tôi có một cái bàn.','Hai trước lượng từ thường dùng 兩: 兩張桌子. 個 có thể đọc nhẹ ge.'),
  card(3,'time-position','Vị trí từ chỉ thời gian','(Thời gian +) chủ ngữ + (thời gian +) động từ','Thời gian thường nằm trước động từ. Hai vị trí trước/sau chủ ngữ đều thường gặp.','我星期六去公園。','Wǒ xīngqíliù qù gōngyuán.','Thứ Bảy tôi đến công viên.','Tránh đặt thời gian sau động từ theo thói quen tiếng Việt.'),
  card(3,'qu','Đi làm gì với 去','Chủ ngữ + 去 + động từ (+ tân ngữ)','去 diễn tả đi để làm một hoạt động.','我們去看電影。','Wǒmen qù kàn diànyǐng.','Chúng mình đi xem phim.','Phân biệt 去看電影 (đi xem phim) và 看電影 (xem phim).'),
  card(3,'topic','Chủ đề trong câu','Chủ đề + lời nhận xét về chủ đề','Đưa điều đang bàn lên trước; phần sau nói về điều đó.','這部電影，我很喜歡。','Zhè bù diànyǐng, wǒ hěn xǐhuān.','Bộ phim này, tôi rất thích.','Chủ đề cần rõ nghĩa trong ngữ cảnh, không đảo mọi thành phần tùy ý.'),
  card(3,'adverb-order','Trật tự 也、都、常常','Chủ ngữ + 也 + 都 + 常常 + động từ','Khi cùng xuất hiện, trật tự thường là 也 → 都 → 常常; chỉ dùng những từ cần cho ý định.','我們也都常常看電影。','Wǒmen yě dōu chángcháng kàn diànyǐng.','Chúng tôi cũng đều thường xem phim.','Các phó từ này đứng trước động từ; đừng đặt sau tân ngữ.'),
  card(3,'ba-suggest','Gợi ý với 吧','Chúng ta + hoạt động + 吧！','吧 làm lời rủ/gợi ý mềm hơn; ý cụ thể do ngữ cảnh quyết định.','我們一起去打球吧！','Wǒmen yīqǐ qù dǎ qiú ba!','Chúng mình cùng đi chơi bóng nhé!','吧 có nhiều chức năng khác; không luôn dịch thành một từ cố định.'),
  card(4,'measures','塊、杯、支、種','Số + lượng từ + danh từ','塊 dùng với tiền/miếng; 杯 cho ly, 支 cho bút/vật dài, 種 cho loại.','我要兩杯茶和一支筆。','Wǒ yào liǎng bēi chá hé yī zhī bǐ.','Tôi muốn hai ly trà và một cây bút.','Chọn lượng từ theo vật; 兩杯茶 và 兩種茶 khác nghĩa.'),
  card(4,'bang','Làm giúp với 幫','Chủ ngữ + 幫 + người + động từ','幫 đứng trước người được giúp rồi đến việc thực hiện.','請幫我買一杯茶。','Qǐng bāng wǒ mǎi yī bēi chá.','Xin mua giúp tôi một ly trà.','幫我買 không có nghĩa “mua tôi”; 我 là người được giúp.'),
  card(4,'de-ellipsis','Lược danh từ sau 的','Phần bổ nghĩa + 的','Khi đối tượng đã rõ, có thể lược danh từ và dùng 的 giữ phần mô tả.','我要大杯的。','Wǒ yào dà bēi de.','Tôi lấy loại ly lớn.','Phải có ngữ cảnh để biết danh từ bị lược là gì.'),
  card(4,'tai-le','Quá… với 太…了','太 + tính từ + 了','Diễn tả mức độ cao; có thể than phiền hoặc khen tùy tính từ và tình huống.','這件衣服太貴了。','Zhè jiàn yīfu tài guì le.','Chiếc áo này đắt quá.','了 trong mẫu này không có nghĩa “đã” của quá khứ.'),
  card(4,'neng','Khả năng với 能','Chủ ngữ + 能 + động từ','能 thường nói khả năng thực hiện hoặc điều kiện cho phép.','你能幫我嗎？','Nǐ néng bāng wǒ ma?','Bạn có thể giúp tôi không?','會 thường nói kỹ năng đã học; 能 tập trung khả năng/điều kiện trong tình huống.'),
  card(4,'duo-number','Hơn một con số với 多','Số tròn + 多 (+ lượng từ)','多 sau số thường cho biết vượt con số đó một khoảng, không phải số chính xác.','這本書三百多塊。','Zhè běn shū sānbǎi duō kuài.','Quyển sách này hơn ba trăm đồng.','三百多 không đồng nghĩa 正好三百; vị trí 多 tùy loại số/lượng từ.'),
  card(5,'you-yidian','Hơi… với 有一點','Chủ ngữ + 有一點 + tính từ','Nêu mức độ nhẹ, thường với cảm giác không mong muốn.','這碗麵有一點辣。','Zhè wǎn miàn yǒu yīdiǎn là.','Tô mì này hơi cay.','有一點辣 = hơi cay; 辣一點 = cay hơn một chút.'),
  card(5,'de','Bổ ngữ trạng thái 得','Động từ + 得 + mô tả','得 đọc nhẹ de, dẫn phần đánh giá cách thực hiện hoặc mức độ/kết quả.','你做得很好。','Nǐ zuò de hěn hǎo.','Bạn làm rất tốt.','Không đặt tân ngữ giữa động từ và 得.',['oxford']),
  card(5,'hui','Kỹ năng với 會','Chủ ngữ + 會 + động từ','會 cho biết kỹ năng có được nhờ học hoặc luyện tập.','我會做牛肉麵。','Wǒ huì zuò niúròumiàn.','Tôi biết nấu mì bò.','Không dùng 有 thay cho 會 khi nói biết làm một việc.'),
  card(5,'dao','Đến nơi với 到','到 + nơi chốn + 去/來 (+ hoạt động)','到 nêu đích đến của việc di chuyển.','我們到餐廳去吃飯。','Wǒmen dào cāntīng qù chī fàn.','Chúng mình đến nhà hàng ăn cơm.','到 còn có chức năng khác ở cấp sau; ở đây chỉ học đích đến.'),
  card(6,'zai','Địa điểm với 在','Sự vật/người + 在 + nơi chốn','在 diễn tả vị trí của người/vật đã được nói đến.','圖書館在學校裡。','Túshūguǎn zài xuéxiào lǐ.','Thư viện ở trong trường.','Phân biệt 在 nêu vị trí và 有 giới thiệu sự tồn tại.'),
  card(6,'existential','Câu tồn tại với 有','Nơi chốn + 有 + người/vật','Giới thiệu có người/vật nào đó ở một nơi.','學校旁邊有一家咖啡店。','Xuéxiào pángbiān yǒu yī jiā kāfēidiàn.','Cạnh trường có một quán cà phê.','Không dùng 是 thay 有 để giới thiệu tồn tại theo mẫu cơ bản này.'),
  card(6,'v-yiv','Lặp động từ V（一）V','V + 一 + V / VV','Làm nhẹ hành động hoặc gợi ý làm một chút.','我們去看一看。','Wǒmen qù kàn yī kàn.','Chúng mình đi xem một chút.','Không lặp theo cách này với mọi tính từ, động từ tình thái hoặc dạng đang diễn ra.'),
  card(6,'bushi','Phủ định một nhận định: 不是','不是 + phần nhận định','不是 có thể phủ định hoặc sửa lại cả nhận định trong ngữ cảnh phù hợp.','我不是不喜歡，只是沒有時間。','Wǒ bù shì bù xǐhuān, zhǐshì méiyǒu shíjiān.','Không phải tôi không thích, chỉ là không có thời gian.','Đây không phải lý do thêm 是 vào mọi câu tính từ.'),
  card(6,'activity-place','Nơi diễn ra hoạt động','Chủ ngữ + 在 + nơi chốn + động từ','Cụm 在 + địa điểm thường đứng trước hành động.','我們在圖書館看書。','Wǒmen zài túshūguǎn kàn shū.','Chúng tôi đọc sách ở thư viện.','Vị trí của kết quả như 放在桌上 là cấu trúc khác, không đảo máy móc.'),
  card(7,'event','Thời gian và địa điểm sự kiện','Sự kiện + (是) + thời gian / 在 + nơi','Nêu lúc diễn ra hoặc nơi tổ chức một sự kiện, phân biệt với thời gian làm một hành động.','生日會在我家。','Shēngrìhuì zài wǒ jiā.','Tiệc sinh nhật ở nhà tôi.','“Tiệc ở đâu” và “Ai đang làm gì ở đâu” dùng chủ ngữ khác nhau.'),
  card(7,'cong-dao','Từ… đến… với 從…到…','從 + mốc đầu + 到 + mốc cuối','Dùng cho khoảng thời gian hoặc quãng từ nơi này đến nơi khác.','我從九點到十點上課。','Wǒ cóng jiǔ diǎn dào shí diǎn shàngkè.','Tôi học từ chín đến mười giờ.','Mốc thời gian khác thời lượng: 一個小時 là một tiếng.'),
  card(7,'progressive','Hành động đang diễn ra: 在','Chủ ngữ + 在 / 正在 + động từ','Mô tả quá trình đang xảy ra ở thời điểm được nói đến.','她在唱歌。','Tā zài chàng gē.','Cô ấy đang hát.','在 + nơi chốn nêu vị trí; 在 + động từ có thể nêu tiến trình.'),
  card(7,'mei','Mỗi… với 每','每 + (số/lượng từ) + danh từ + 都…','每 nêu mỗi đơn vị/người; thường đi cùng 都 để nhấn mạnh sự đều đặn.','我每天都練習。','Wǒ měitiān dōu liànxí.','Ngày nào tôi cũng luyện tập.','每天 không cần 個; 每個星期 có 個. Học cả cụm.'),
  card(7,'keyi','Xin phép với 可以','可以 + động từ + 嗎？','可以 thường dùng để hỏi/cho sự cho phép, tùy hoàn cảnh cũng nói khả năng chấp nhận được.','這裡可以拍照嗎？','Zhèlǐ kěyǐ pāizhào ma?','Ở đây được chụp ảnh không?','Không thay mọi 可以 bằng 會; kỹ năng và sự cho phép khác nhau.'),
  card(8,'gen','Cùng ai với 跟','Chủ ngữ + 跟 + người + động từ','跟 nêu người cùng tham gia một hoạt động.','我跟朋友坐火車去臺南。','Wǒ gēn péngyǒu zuò huǒchē qù Táinán.','Tôi cùng bạn đi tàu hỏa đến Đài Nam.','跟 còn có thể nối hai danh từ; ở đây tập trung cụm cùng ai làm gì.'),
  card(8,'zenme','Hỏi cách thức với 怎麼','Chủ ngữ + 怎麼 + động từ？','怎麼 hỏi cách làm hoặc phương tiện trong ngữ cảnh.','你怎麼去學校？','Nǐ zěnme qù xuéxiào?','Bạn đến trường bằng cách nào?','怎麼 có thể hỏi nguyên nhân khi ngữ cảnh khác; không luôn dịch “bằng cách nào”.'),
  card(8,'bijiao','So sánh ngầm với 比較','Chủ ngữ + 比較 + tính từ','Đối tượng so sánh có thể đã rõ trong ngữ cảnh nên không nhắc lại.','我覺得火車票比較便宜。','Wǒ juéde huǒchēpiào bǐjiào piányí.','Tôi thấy vé tàu hỏa rẻ hơn.','比較 là phó từ trong mẫu này, không cần thêm một 比 ngay sau nó.'),
  card(8,'youyou','Vừa… vừa… với 又…又…','又 + tính từ 1 + 又 + tính từ 2','Nêu hai đặc tính cùng có ở một đối tượng.','這家店又近又便宜。','Zhè jiā diàn yòu jìn yòu piányí.','Cửa hàng này vừa gần vừa rẻ.','Mẫu ở đây nối đặc tính; hai hành động đồng thời thường học mẫu 一邊…一邊… ở phần sau.'),
  card(8,'bi','So sánh hơn với 比','A + 比 + B + tính từ','Nêu rõ hai đối tượng được so trên cùng một đặc tính.','高鐵比火車快。','Gāotiě bǐ huǒchē kuài.','Tàu cao tốc nhanh hơn tàu hỏa thông thường.','Mẫu cơ bản không thêm 很 trước tính từ sau 比.'),
  card(9,'when-duration','Thời điểm và thời lượng','幾點 / 什麼時候 ↔ 多久','Thời điểm trả lời “khi nào”; thời lượng trả lời “bao lâu”.','我九點上課，上兩個小時。','Wǒ jiǔ diǎn shàngkè, shàng liǎng ge xiǎoshí.','Tôi vào học lúc chín giờ, học hai tiếng.','兩點 = mốc hai giờ; 兩個小時 = thời lượng hai tiếng.'),
  card(9,'duration','Bổ ngữ thời lượng','Động từ + thời lượng (+ 的 + tân ngữ)','Thời lượng sau động từ nói việc kéo dài bao lâu; khi có tân ngữ cần chọn mẫu phù hợp.','我每天學一個小時的中文。','Wǒ měitiān xué yī ge xiǎoshí de Zhōngwén.','Mỗi ngày tôi học tiếng Trung một tiếng.','Không đặt thời lượng theo vị trí của từ chỉ thời điểm.'),
  card(9,'deshihou','Khi… với 的時候','Cụm từ/mệnh đề + 的時候','Biến hoạt động/tình huống thành khung thời gian cho sự việc khác.','放假的時候，我想去旅行。','Fàngjià de shíhòu, wǒ xiǎng qù lǚxíng.','Khi được nghỉ, tôi muốn đi du lịch.','的時候 là khung “khi”; không đồng nghĩa “trong bao lâu”.'),
  card(9,'sometimes','Có lúc… có lúc…','有時候…，有時候…','Nêu những hoạt động/tình huống thay đổi ở các lần khác nhau.','我有時候看書，有時候看電影。','Wǒ yǒu shíhou kàn shū, yǒu shíhou kàn diànyǐng.','Có lúc tôi đọc sách, có lúc xem phim.','Hai hoạt động trong mẫu này không nhất thiết xảy ra đồng thời.'),
  card(9,'yaoshi','Nếu… thì…','要是 + điều kiện，(就) + kết quả','Nêu kết quả phụ thuộc vào một điều kiện giả định.','要是下雨，我就不去。','Yàoshì xiàyǔ, wǒ jiù bù qù.','Nếu trời mưa thì tôi không đi.','Đừng dùng 因為 khi muốn nói điều kiện chưa chắc xảy ra.'),
  card(10,'vvkan','Làm thử xem: VV看','Động từ lặp + 看','Gợi ý làm thử để xem cảm giác hoặc kết quả; 看 ở đây không nhất thiết là nhìn.','這個水果很好吃，你吃吃看。','Zhège shuǐguǒ hěn hǎochī, nǐ chī chi kàn.','Trái cây này ngon, bạn ăn thử xem.','Không hiểu 看 trong 吃吃看 là vừa ăn vừa nhìn.'),
  card(10,'redup-adj','Lặp tính từ','AA 的 / AABB 的','Một số tính từ lặp tạo miêu tả sinh động hoặc nhấn mạnh đặc tính theo mẫu quen dùng.','這個西瓜大大的。','Zhège xīguā dàdà de.','Quả dưa hấu này to lắm.','Không tùy ý lặp mọi tính từ; mẫu lặp thường không đi với 很 ngay trước.'),
  card(10,'relative','Mệnh đề bổ nghĩa với 的','Mệnh đề + 的 + danh từ','Mệnh đề đứng trước danh từ để xác định người/vật đang nói đến.','我買的芒果很甜。','Wǒ mǎi de mángguǒ hěn tián.','Xoài tôi mua rất ngọt.','Danh từ chính ở sau 的; không giữ thứ tự “xoài mà tôi mua” của tiếng Việt.'),
  card(10,'change-le','Tình trạng thay đổi với 了','Tình trạng mới + 了','了 cuối câu có thể báo sự thay đổi hoặc tình hình mới.','天氣變熱了。','Tiānqì biàn rè le.','Trời nóng lên rồi.','了 không phải hậu tố quá khứ; thời điểm do ngữ cảnh xác định.',['ntnu-guide']),
  card(10,'because','Vì… nên…','因為 + lý do，所以 + kết quả','Nối nguyên nhân với kết quả; trong ngữ cảnh rõ có thể lược một liên từ.','因為水果很新鮮，所以我買了兩個。','Yīnwèi shuǐguǒ hěn xīnxiān, suǒyǐ wǒ mǎi le liǎng ge.','Vì trái cây rất tươi nên tôi mua hai quả.','因為 là lý do thực tế được nêu, khác giả định 要是.'),
  card(11,'lai','Đến để làm gì với 來','來 + động từ (+ tân ngữ)','來 có thể giới thiệu mục đích đến một nơi.','我來看房子。','Wǒ lái kàn fángzi.','Tôi đến xem nhà.','Chọn 來/去 theo hướng nhìn của người nói và ngữ cảnh.'),
  card(11,'jiu-soon','Sớm/chỉ cần thế với 就','Mốc sớm/ít + 就 + động từ','就 có thể cho thấy việc xảy ra sớm hoặc dễ đạt hơn dự kiến.','走五分鐘就到。','Zǒu wǔ fēnzhōng jiù dào.','Đi bộ chỉ năm phút là đến.','就 có nhiều chức năng; không luôn dịch thành “thì”.'),
  card(11,'you-subject','Giới thiệu chủ thể với 有','有 + người/vật + vị ngữ','Giới thiệu người/vật chưa xác định rồi nói việc họ làm hoặc đặc điểm của họ.','有人來看房子。','Yǒu rén lái kàn fángzi.','Có người đến xem nhà.','有人 không phải tên riêng và không xác định một người đã biết.'),
  card(11,'hui-types','Các nghĩa của 會','會 + động từ / trạng thái','Ngoài kỹ năng, 會 có thể nói dự đoán hoặc khả năng sự việc xảy ra trong hoàn cảnh.','明天會下雨。','Míngtiān huì xiàyǔ.','Ngày mai có thể/sẽ mưa.','Không dịch 會下雨 thành “biết mưa”.'),
  card(11,'shan','Lượng từ 扇','Số + 扇 + cửa/cửa sổ','扇 shàn dùng đếm cánh cửa, cửa sổ trong bài nhà ở.','這個房間有兩扇窗戶。','Zhège fángjiān yǒu liǎng shàn chuānghù.','Phòng này có hai cửa sổ.','Chú ý 扇 ở đây đọc shàn, khác một số cách dùng động từ shān.'),
  card(12,'xian-zai','Trước… rồi…','先 + việc 1，再 + việc 2','Nêu trình tự dự định làm: bước đầu rồi bước tiếp theo.','我先複習，再練習口說。','Wǒ xiān fùxí, zài liànxí kǒushuō.','Tôi ôn bài trước rồi luyện nói.','再 zài khác 在 zài dù cùng âm.'),
  card(12,'shi-de','Nhấn mạnh chi tiết với 是…的','Chủ ngữ + 是 + chi tiết + động từ + 的','Trong tình huống sự việc đã được biết, mẫu này nhấn mạnh lúc nào, ở đâu, bằng cách nào hoặc ai.','我是九月來臺灣的。','Wǒ shì jiǔ yuè lái Táiwān de.','Tôi đến Đài Loan vào tháng Chín.','Không coi 是…的 là dấu hiệu quá khứ cho mọi động từ.'),
  card(12,'yihou','Sau khi… với 以後','Mệnh đề / mốc thời gian + 以後','以後 đặt sau hoạt động/mốc để chỉ phần thời gian sau đó.','下課以後，我去圖書館。','Xiàkè yǐhòu, wǒ qù túshūguǎn.','Sau khi tan học tôi đến thư viện.','Trước khi dùng 以前; 以後 là sau khi/sau này.'),
  card(12,'hao-nan','好 / 難 + động từ','好 / 難 + động từ','Tổ hợp quen dùng có thể nói dễ/khó hoặc cảm giác đánh giá: 好寫 dễ viết, 難寫 khó viết; 好吃 ngon.','這個字很難寫。','Zhège zì hěn nán xiě.','Chữ này khó viết.','好吃 nghĩa là ngon, không chỉ “dễ ăn”; học ý nghĩa từng tổ hợp.'),
  card(13,'yi-jiu','Vừa… là… với 一…就…','一 + việc 1，就 + việc 2','Việc thứ hai theo sát điều kiện/thời điểm của việc thứ nhất.','朋友一到，我們就吃飯。','Péngyǒu yī dào, wǒmen jiù chī fàn.','Bạn bè vừa đến là chúng tôi ăn cơm.','Trong mẫu này 一 không dùng để đếm số một.'),
  card(13,'completed-le','Hành động hoàn thành với 了','Động từ + 了 + tân ngữ','Đánh dấu một sự kiện được nhìn như đã hoàn tất; thời gian còn tùy ngữ cảnh.','我買了兩個蛋糕。','Wǒ mǎi le liǎng ge dàngāo.','Tôi đã mua hai chiếc bánh kem.','Không gắn 了 vào mọi câu có 昨天; 了 không phải thì quá khứ.',['ntnu-guide']),
  card(13,'bu-mei','Phân biệt 不 và 沒','不 + trạng thái/ý định; 沒(有) + việc không/chưa xảy ra','Chọn theo ý nghĩa, không chỉ theo thời gian. 有 phủ định bằng 沒有.','我不喝咖啡，今天也沒喝。','Wǒ bù hē kāfēi, jīntiān yě méi hē.','Tôi không uống cà phê; hôm nay cũng không uống.','Khi phủ định sự kiện bằng 沒, thường bỏ 了 đánh dấu hoàn thành.'),
  card(13,'wh-all','Bao quát với từ hỏi và 都','Từ hỏi + 都 + vị ngữ','誰、什麼、哪裡… với 都 có thể bao quát tất cả, không còn là câu hỏi thông tin.','這些水果我都喜歡，什麼都想吃。','Zhèxiē shuǐguǒ wǒ dōu xǐhuān, shénme dōu xiǎng chī.','Tôi thích các loại trái cây này, loại nào cũng muốn ăn.','什麼 trong mẫu bao quát không nhất thiết mang nghĩa nghi vấn “cái gì?”.'),
  card(13,'duo-shao','Làm nhiều/ít hơn với 多 / 少','多 / 少 + động từ (+ lượng chênh)','Đặt trước động từ để nói làm nhiều/ít hơn một mức ngữ cảnh đã biết.','今天我多寫了三個字。','Jīntiān wǒ duō xiě le sān ge zì.','Hôm nay tôi viết thêm ba chữ.','多寫三個字 là viết thêm ba chữ; 寫三個字 là tổng cộng viết ba chữ.'),
  card(13,'shibushi','Xác nhận với 是不是','是不是 + nhận định？','Dùng để xin xác nhận một điều người nói đang suy đoán.','你是不是喜歡巧克力蛋糕？','Nǐ shì bù shì xǐhuān qiǎokèlì dàngāo?','Có phải bạn thích bánh kem sô cô la không?','Thường không thêm 嗎 vào cuối mẫu A不A này.'),
  card(13,'same','Giống nhau với 跟…一樣','A + 跟 + B + 一樣 (+ đặc tính)','So sánh hai đối tượng giống nhau ở điểm được nói đến.','這個蛋糕跟那個一樣大。','Zhège dàngāo gēn nàge yīyàng dà.','Chiếc bánh này to bằng chiếc kia.','Đặc tính sau 一樣 nêu tiêu chí bằng nhau; không thêm 比 trong cùng mẫu cơ bản.'),
  card(14,'duration-le','Thời lượng sau động từ + 了','Động từ + 了 + thời lượng (+ tân ngữ)','Nêu lượng thời gian của một sự việc; riêng mẫu này chưa tự kết luận việc còn tiếp diễn.','昨天我等了二十分鐘。','Zuótiān wǒ děng le èrshí fēnzhōng.','Hôm qua tôi đã đợi hai mươi phút.','Muốn biết đã dừng hay còn tiếp diễn phải đọc ngữ cảnh và cấu trúc cả câu.'),
  card(14,'double-le','Hai 了: kéo dài đến hiện tại','Động từ + 了 + thời lượng (+ tân ngữ) + 了','Thường nói thời lượng đã tích lũy đến hiện tại và tình huống vẫn còn tiếp diễn.','我學了三個月中文了。','Wǒ xué le sān ge yuè Zhōngwén le.','Tôi học tiếng Trung được ba tháng rồi.','Hai 了 có vai trò khác nhau, không phải viết lặp vô nghĩa.'),
  card(14,'kuai-le','Sắp… rồi với 快…了','快 + sự việc + 了','Báo một thay đổi/sự việc gần xảy ra.','春天快到了。','Chūntiān kuài dào le.','Mùa xuân sắp đến rồi.','快 trong mẫu này là “sắp”, không chỉ tốc độ nhanh.'),
  card(14,'geng','Càng/hơn nữa với 更','(A + 比 + B) + 更 + tính từ','更 tăng mức so sánh đã rõ hoặc nhấn mạnh một mức cao hơn nữa.','今天比昨天更冷。','Jīntiān bǐ zuótiān gèng lěng.','Hôm nay còn lạnh hơn hôm qua.','Không thay 更 bằng 很 trong mẫu 比 cơ bản.'),
  card(14,'meiyou-compare','Không bằng với 沒有','A + 沒有 + B + tính từ','Diễn tả A kém B về mức độ của đặc tính.','今天沒有昨天冷。','Jīntiān méiyǒu zuótiān lěng.','Hôm nay không lạnh bằng hôm qua.','沒有 ở đây dùng so sánh, không phải không sở hữu.'),
  card(15,'wh-vague','Từ hỏi dùng để nói chưa xác định','Từ hỏi trong câu không nhất thiết hỏi','什麼/哪裡 có thể chỉ điều/nơi chưa xác định khi ngữ cảnh không đặt câu hỏi.','我想吃點什麼。','Wǒ xiǎng chī diǎn shénme.','Tôi muốn ăn chút gì đó.','Phân biệt với câu hỏi 你想吃什麼？ bằng người nói, ngữ điệu và ngữ cảnh.'),
  card(15,'ba','Xử lý đối tượng với 把','Chủ ngữ + 把 + tân ngữ xác định + động từ + bổ sung','Làm rõ vật chịu tác động và kết quả/nơi đến của hành động.','請把這杯水放在桌上。','Qǐng bǎ zhè bēi shuǐ fàng zài zhuō shàng.','Xin đặt ly nước này lên bàn.','Tân ngữ cần xác định/đã biết; không dùng tùy ý với 是、有、喜歡. Phủ định đứng trước 把.',['oxford']),
  card(15,'vle-jiu','Làm xong A rồi liền B','Động từ + 了 + tân ngữ，就 + việc sau','Nêu hành động trước làm điều kiện trình tự cho hành động sau; có thể nói lịch sinh hoạt hoặc dự định.','我下了課就回家。','Wǒ xià le kè jiù huí jiā.','Tan học là tôi về nhà ngay.','了 trong mệnh đề đầu không tự biến cả câu thành chuyện quá khứ.'),
  card(15,'yidian','Một chút với 一點','Tính từ + 一點 / 一點 + danh từ','Sau tính từ, 一點 có thể điều chỉnh mức độ; trước danh từ nói lượng ít.','請說慢一點。','Qǐng shuō màn yīdiǎn.','Xin nói chậm hơn một chút.','有一點慢 là hơi chậm; 慢一點 là chậm hơn một chút.'),
  card(15,'de-compare','So sánh hành động với 得','A + động từ + 得 + 比 + B + tính từ','So sánh cách hoặc mức độ làm một việc, dùng 得 sau động từ.','他走得比我快。','Tā zǒu de bǐ wǒ kuài.','Anh ấy đi nhanh hơn tôi.','Không đặt tân ngữ giữa động từ và 得.',['oxford']),
  card(15,'compare-degree','Mức chênh lệch trong so sánh','A + 比 + B + tính từ + 多了 / 一點','Nêu chênh lệch lớn hoặc nhỏ thay vì chỉ nói hơn.','今天比昨天冷多了。','Jīntiān bǐ zuótiān lěng duō le.','Hôm nay lạnh hơn hôm qua nhiều.','多了 đặt sau tính từ để nêu chênh lệch; không nói 很冷 ngay sau 比 trong mẫu này.'),
  card(15,'separable','Động từ ly hợp','Động từ–tân ngữ có thể tách','Một số tổ hợp như 睡覺、上課、洗澡 gồm động từ và thành phần danh từ nên có thể chen thời lượng/了 theo mẫu.','我昨天睡了八個小時的覺。','Wǒ zuótiān shuì le bā ge xiǎoshí de jiào.','Hôm qua tôi ngủ tám tiếng.','Không coi mọi động từ hai âm tiết đều ly hợp; học theo từng tổ hợp.')
];

pronunciation.notes[pronunciation.notes.length-1] = 'Web là tài liệu đồng hành cho đủ 15 bài của 當代中文課程 1 bạn cung cấp: luyện tất cả kỹ năng bằng ví dụ mới. Hoàn thành phần này không đồng nghĩa đạt toàn bộ năng lực A2 hoặc các tập sau.';
pronunciation.notes.push('Khi đếm: 一 yī, 二 èr, 三 sān, 四 sì, 五 wǔ, 六 liù, 七 qī, 八 bā, 九 jiǔ, 十 shí. Trước lượng từ thường nói 兩 liǎng thay cho 二.');
for (const unit of lessons) unit.grammarIds = grammar.filter((item) => item.bookNumber === unit.bookNumber).map((item) => item.id);
